// 3D Modeler — photo in, real GLB out, generated by TRELLIS 2 (Microsoft,
// MIT open source) running on the founder's own PC as the GPU node.
//
// Flow (founder architecture, 2026-11-12/14): the Tools hub panel calls
// this function to create a job (sign-in + Global Credit charge, the
// generate-sfh-image pattern); the PC node polls `claim`, downloads the
// photo, runs TRELLIS 2 locally, uploads the GLB through a signed URL and
// calls `complete`. Job state lives as JSON in the studio-published
// bucket (the platform's no-migration store). If the PC is off there is
// no fresh heartbeat and `status`/`create` report the engine offline —
// nothing else on the platform depends on it.
//
// Credits: Imagine Engine Studios Corp.
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "npm:@supabase/supabase-js@2.57.2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version, x-node-key",
};

const BUCKET = "studio-published";
const PREFIX = "models-3d";
const NODE_FRESH_MS = 90_000; // heartbeat older than this = engine offline
const RUNNING_STALE_MS = 45 * 60_000; // a claimed job older than this is dead

// Quality tiers: Credits are the founder-suggested member prices
// (5/10/15, 2026-11-12 — one-line change when she decides). minVramGb is
// what TRELLIS 2 needs locally: ~12GB at 512, ~24GB for the full tiers.
const TIERS: Record<string, { credits: number; minVramGb: number }> = {
  "512": { credits: 5, minVramGb: 12 },
  "1024": { credits: 10, minVramGb: 24 },
  "1536": { credits: 15, minVramGb: 24 },
};

type Job = {
  id: string;
  userId: string;
  tier: string;
  charged: number;
  status: "queued" | "running" | "done" | "failed";
  imageUrl: string;
  modelUrl?: string;
  error?: string;
  createdAt: number;
  claimedAt?: number;
  finishedAt?: number;
};

const json = (d: unknown, status = 200) =>
  new Response(JSON.stringify(d), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  const admin = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
    { auth: { persistSession: false } }
  );

  const store = {
    async read<T>(path: string): Promise<T | null> {
      const { data } = await admin.storage.from(BUCKET).download(path);
      if (!data) return null;
      try { return JSON.parse(await data.text()) as T; } catch { return null; }
    },
    async write(path: string, value: unknown) {
      const { error } = await admin.storage.from(BUCKET).upload(
        path,
        new Blob([JSON.stringify(value)], { type: "application/json" }),
        { upsert: true, contentType: "application/json", cacheControl: "10" }
      );
      if (error) throw new Error("Storage write failed: " + error.message);
    },
  };
  const jobPath = (id: string) => `${PREFIX}/jobs/${id}.json`;
  const outPath = (id: string) => `${PREFIX}/outputs/${id}.glb`;

  try {
    const body = await req.json().catch(() => ({}));
    const action = String(body.action || "");

    /* ---- GPU node actions (shared-secret header, no user session) ---- */
    const nodeKey = Deno.env.get("MODEL_NODE_KEY") ?? "";
    const isNodeAction = ["heartbeat", "claim", "complete", "fail"].includes(action);
    if (isNodeAction) {
      if (!nodeKey) return json({ error: "node_not_configured", message: "MODEL_NODE_KEY is not set on the platform yet." }, 501);
      if ((req.headers.get("x-node-key") || "") !== nodeKey) return json({ error: "Bad node key" }, 403);

      if (action === "heartbeat") {
        await store.write(`${PREFIX}/node.json`, {
          lastSeen: Date.now(),
          gpu: String(body.gpu || "unknown").slice(0, 80),
          vramGb: Number(body.vramGb) || 0,
        });
        return json({ ok: true });
      }

      if (action === "claim") {
        const { data: files } = await admin.storage.from(BUCKET)
          .list(`${PREFIX}/jobs`, { limit: 50, sortBy: { column: "created_at", order: "asc" } });
        for (const f of (files || []).filter((x) => x.name.endsWith(".json")).slice(0, 12)) {
          const job = await store.read<Job>(`${PREFIX}/jobs/${f.name}`);
          if (!job) continue;
          if (job.status === "running" && job.claimedAt && Date.now() - job.claimedAt > RUNNING_STALE_MS) {
            job.status = "failed"; job.error = "The 3D engine stopped mid-job."; job.finishedAt = Date.now();
            await store.write(jobPath(job.id), job);
            await refund(admin, job);
            continue;
          }
          if (job.status !== "queued") continue;
          job.status = "running"; job.claimedAt = Date.now();
          await store.write(jobPath(job.id), job);
          const { data: signed, error } = await admin.storage.from(BUCKET).createSignedUploadUrl(outPath(job.id));
          if (error || !signed) throw new Error("Could not prepare the result upload");
          return json({
            job: { id: job.id, tier: job.tier, imageUrl: job.imageUrl },
            uploadUrl: signed.signedUrl,
            publicUrl: admin.storage.from(BUCKET).getPublicUrl(outPath(job.id)).data.publicUrl,
          });
        }
        return json({ job: null });
      }

      if (action === "complete") {
        const job = await store.read<Job>(jobPath(String(body.jobId || "")));
        if (!job) return json({ error: "Job not found" }, 404);
        const { data } = await admin.storage.from(BUCKET).download(outPath(job.id));
        if (!data) return json({ error: "Result file missing — upload the GLB before completing" }, 409);
        job.status = "done";
        job.modelUrl = admin.storage.from(BUCKET).getPublicUrl(outPath(job.id)).data.publicUrl;
        job.finishedAt = Date.now();
        await store.write(jobPath(job.id), job);
        return json({ ok: true, modelUrl: job.modelUrl });
      }

      if (action === "fail") {
        const job = await store.read<Job>(jobPath(String(body.jobId || "")));
        if (!job) return json({ error: "Job not found" }, 404);
        if (job.status !== "done" && job.status !== "failed") {
          job.status = "failed";
          job.error = String(body.error || "Generation failed on the 3D engine").slice(0, 300);
          job.finishedAt = Date.now();
          await store.write(jobPath(job.id), job);
          await refund(admin, job);
        }
        return json({ ok: true });
      }
    }

    /* ---- member actions (signed-in session) ---- */
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) throw new Error("No authorization header");
    const token = authHeader.replace("Bearer ", "");
    const { data: userData, error: userError } = await admin.auth.getUser(token);
    if (userError || !userData.user) throw new Error("Unauthorized");
    const user = userData.user;
    const { data: roleRow } = await admin.from("user_roles").select("role")
      .eq("user_id", user.id).eq("role", "admin").maybeSingle();
    const isAdmin = !!roleRow;

    const node = await store.read<{ lastSeen: number; gpu: string; vramGb: number }>(`${PREFIX}/node.json`);
    const online = !!node && Date.now() - node.lastSeen < NODE_FRESH_MS;
    const tiersFor = (vram: number) => Object.keys(TIERS).filter((t) => TIERS[t].minVramGb <= (vram || 0));

    if (action === "status") {
      return json({
        online,
        gpu: online ? node!.gpu : null,
        vramGb: online ? node!.vramGb : null,
        tiers: online ? tiersFor(node!.vramGb) : [],
        prices: Object.fromEntries(Object.entries(TIERS).map(([t, v]) => [t, v.credits])),
      });
    }

    if (action === "create") {
      const tier = String(body.tier || "512");
      if (!TIERS[tier]) return json({ error: "Unknown quality tier" }, 400);
      if (!online) {
        return json({ error: "engine_offline", message: "The 3D engine is offline right now — the computer that runs it is switched off. Nothing was charged." }, 503);
      }
      if (!tiersFor(node!.vramGb).includes(tier)) {
        return json({ error: "tier_unavailable", message: `The connected engine (${node!.gpu}, ${node!.vramGb}GB) can't run the ${tier} tier.` }, 400);
      }
      const m = String(body.imageDataUrl || "").match(/^data:image\/(png|jpeg|jpg|webp);base64,(.+)$/);
      if (!m) return json({ error: "Send one photo (PNG, JPG or WebP)" }, 400);
      const bytes = Uint8Array.from(atob(m[2]), (c) => c.charCodeAt(0));
      if (bytes.length < 1024 || bytes.length > 12 * 1024 * 1024) return json({ error: "Photo must be between 1KB and 12MB" }, 400);

      const id = crypto.randomUUID();
      const ext = m[1] === "jpeg" ? "jpg" : m[1];
      const inPath = `${PREFIX}/inputs/${id}.${ext}`;
      const { error: upErr } = await admin.storage.from(BUCKET)
        .upload(inPath, bytes, { contentType: `image/${m[1]}`, upsert: false });
      if (upErr) throw new Error("Could not save the photo: " + upErr.message);
      const imageUrl = admin.storage.from(BUCKET).getPublicUrl(inPath).data.publicUrl;

      // Global Credit charge — same wallet as every AI action; admins 0.
      const price = TIERS[tier].credits;
      let charged = 0;
      let balance: number | null = null;
      if (!isAdmin && price > 0) {
        const { data: nb, error: consumeError } = await admin.rpc("ai_credits_consume", {
          _user_id: user.id, _amount: price, _reason: `model3d:${tier}`,
        });
        if (consumeError) throw new Error("Credit check failed: " + consumeError.message);
        if (Number(nb) < 0) {
          return json({
            error: "limit_reached",
            message: "You're out of Global Credits. Top up or upgrade your plan to keep creating.",
            credits: 0,
          }, 402);
        }
        charged = price;
        balance = Number(nb);
      } else {
        const { data: bal } = await admin.rpc("ai_credits_sync", { _user_id: user.id });
        balance = Number(bal ?? 0);
      }

      const job: Job = { id, userId: user.id, tier, charged, status: "queued", imageUrl, createdAt: Date.now() };
      try {
        await store.write(jobPath(id), job);
      } catch (e) {
        // Charged but the job never landed — give the Credits straight back.
        await refund(admin, job);
        throw e;
      }
      try {
        await admin.from("api_usage_logs").insert({
          user_id: user.id, service_name: "sfh-3d-modeler", endpoint: "generate-3d-model",
          request_count: 1, metadata: { tier, jobId: id },
        });
      } catch { /* usage log is best-effort */ }
      return json({ jobId: id, status: "queued", credits: balance });
    }

    if (action === "poll") {
      const job = await store.read<Job>(jobPath(String(body.jobId || "")));
      if (!job || (job.userId !== user.id && !isAdmin)) return json({ error: "Job not found" }, 404);
      if (job.status === "running" && job.claimedAt && Date.now() - job.claimedAt > RUNNING_STALE_MS) {
        job.status = "failed"; job.error = "The 3D engine stopped mid-job."; job.finishedAt = Date.now();
        await store.write(jobPath(job.id), job);
        await refund(admin, job);
      }
      return json({ status: job.status, modelUrl: job.modelUrl || null, error: job.error || null, tier: job.tier });
    }

    return json({ error: "Unknown action" }, 400);
  } catch (error) {
    console.error("generate-3d-model error:", error);
    return json({ error: (error as Error).message || "3D generation failed" }, 500);
  }
});

/** Give the job's Credits back exactly once (the ledger ref is the job). */
async function refund(admin: ReturnType<typeof createClient>, job: Job) {
  if (!job.charged || job.charged <= 0) return;
  try {
    await admin.rpc("ai_credits_grant", {
      _user_id: job.userId,
      _amount: job.charged,
      _reason: "model3d:refund",
      _ref: `model3d:refund:${job.id}`,
    });
  } catch { /* the deterministic ref keeps a retry safe */ }
}
